package com.vibeguard.samples.deletion; import java.util.Map; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; /** Enforces owner-only account data export and deletion. */ @RestController @RequestMapping("/api/accounts") public class AccountController { @Value("${ACCOUNT_API_KEY:}") private String apiKey; @Value("${ACCOUNT_OWNER_ID:}") private String ownerId; private boolean deleted; @GetMapping("/{id}/export") public ResponseEntity<Map<String,Object>> export(@RequestHeader("X-Account-Key") String key,@PathVariable String id){if(!owner(key,id))return ResponseEntity.status(403).build();if(deleted)return ResponseEntity.notFound().build();return ResponseEntity.ok(Map.of("id",id,"exportStatus","READY"));}@DeleteMapping("/{id}") public ResponseEntity<Void> delete(@RequestHeader("X-Account-Key") String key,@PathVariable String id){if(!owner(key,id))return ResponseEntity.status(403).build();deleted=true;return ResponseEntity.noContent().build();}private boolean owner(String key,String id){return !apiKey.isBlank()&&!ownerId.isBlank()&&apiKey.equals(key)&&ownerId.equals(id);} }
